import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import {
    CurrencyDollarIcon, UsersIcon, PercentIcon,
    BriefcaseIcon, CheckCircleIcon, ExclamationTriangleIcon,
    ArrowPathIcon, CogIcon, ChartBarIcon
} from '@heroicons/react/24/outline';
import toast from 'react-hot-toast';
import salesRepService from '../../services/salesRepService';
import commissionService from '../../services/commissionService';
import StatCard from '../../components/ui/StatCard';
import SectionCard from '../../components/ui/SectionCard';
import StatusBadge from '../../components/ui/StatusBadge';
import PageHeader from '../../components/ui/PageHeader';
import { DollarSign, Percent, Users, TrendingUp } from 'lucide-react';

const structureInfo = {
    commission_only: {
        title: 'Commission Only',
        description: 'Earns a percentage on each completed order. No base salary.',
        icon: PercentIcon,
        color: 'gold',
        bgClass: 'from-gold-50 to-gold-100 dark:from-gold-900/10 dark:to-gold-900/20',
        borderClass: 'border-gold-200 dark:border-gold-800',
    },
    salary_only: {
        title: 'Salary Only',
        description: 'Fixed monthly salary. No per-order commission.',
        icon: BriefcaseIcon,
        color: 'teal',
        bgClass: 'from-teal-50 to-teal-100 dark:from-teal-900/10 dark:to-teal-900/20',
        borderClass: 'border-teal-200 dark:border-teal-800',
    },
    salary_plus_commission: {
        title: 'Salary + Commission',
        description: 'Base salary plus a percentage on each completed order.',
        icon: ChartBarIcon,
        color: 'navy',
        bgClass: 'from-brand-50 to-brand-100 dark:from-brand-800/20 dark:to-brand-900/20',
        borderClass: 'border-brand-200 dark:border-brand-700',
    },
};

const CommissionSettings = () => {
    const [selectedRep, setSelectedRep] = useState(null);
    const [structure, setStructure] = useState('');
    const [baseSalary, setBaseSalary] = useState('');
    const [commissionPercentage, setCommissionPercentage] = useState('');
    const queryClient = useQueryClient();

    const { data: salesReps, isLoading } = useQuery({
        queryKey: ['sales-reps-commission'],
        queryFn: () => salesRepService.getAllSalesReps()
    });

    const updateMutation = useMutation({
        mutationFn: (data) => commissionService.setCommission(data.userId, data),
        onSuccess: () => {
            toast.success('Commission structure updated');
            queryClient.invalidateQueries(['sales-reps-commission']);
            queryClient.invalidateQueries(['sales-reps']);
            resetForm();
        },
        onError: (error) => toast.error(error.response?.data?.message || 'Failed to update')
    });

    const processSalaryMutation = useMutation({
        mutationFn: () => commissionService.processSalaries(),
        onSuccess: (data) => toast.success(`Processed ${data.data?.length || 0} salary payments`),
        onError: () => toast.error('Failed to process salaries')
    });

    const resetForm = () => {
        setSelectedRep(null);
        setStructure('');
        setBaseSalary('');
        setCommissionPercentage('');
    };

    const handleSelectRep = (rep) => {
        setSelectedRep(rep);
        setStructure(rep.commission?.structure || '');
        setBaseSalary(rep.commission?.baseSalary?.toString() || '');
        setCommissionPercentage(rep.commission?.commissionPercentage?.toString() || '');
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!selectedRep || !structure) return;
        updateMutation.mutate({
            userId: selectedRep.id,
            structure,
            baseSalary: parseFloat(baseSalary) || 0,
            commissionPercentage: parseFloat(commissionPercentage) || 0,
        });
    };

    const structureCounts = {
        commission_only: salesReps?.filter(r => r.commission?.structure === 'commission_only').length || 0,
        salary_only: salesReps?.filter(r => r.commission?.structure === 'salary_only').length || 0,
        salary_plus_commission: salesReps?.filter(r => r.commission?.structure === 'salary_plus_commission').length || 0,
        none: salesReps?.filter(r => !r.commission).length || 0,
    };

    const hasValidStructure = structure && (
        (['salary_only', 'salary_plus_commission'].includes(structure) && baseSalary && parseFloat(baseSalary) > 0) ||
        (structure === 'commission_only' && commissionPercentage && parseFloat(commissionPercentage) > 0) ||
        (structure === 'salary_plus_commission' && baseSalary && commissionPercentage)
    );

    return (
        <div className="space-y-6">
            <PageHeader
                icon={CurrencyDollarIcon}
                title="Commission Settings"
                description="Configure earning structures for sales representatives"
                actions={
                    <button
                        onClick={() => processSalaryMutation.mutate()}
                        disabled={processSalaryMutation.isLoading}
                        className="flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-gold-500 to-gold-600 text-white rounded-xl hover:from-gold-600 hover:to-gold-700 transition-all font-semibold shadow-lg shadow-gold-500/25 text-sm disabled:opacity-50"
                    >
                        <ArrowPathIcon className={`w-5 h-5 ${processSalaryMutation.isLoading ? 'animate-spin' : ''}`} />
                        Process Monthly Salaries
                    </button>
                }
            />

            {/* Overview Stats */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard label="Commission Only" value={structureCounts.commission_only} icon={Percent} color="gold" loading={isLoading} />
                <StatCard label="Salary Only" value={structureCounts.salary_only} icon={DollarSign} color="teal" loading={isLoading} />
                <StatCard label="Salary + Commission" value={structureCounts.salary_plus_commission} icon={TrendingUp} color="navy" loading={isLoading} />
                <StatCard label="Not Configured" value={structureCounts.none} icon={Users} color="rose" loading={isLoading} />
            </div>

            {/* Structure Info Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {Object.entries(structureInfo).map(([key, info]) => (
                    <motion.div
                        key={key}
                        whileHover={{ y: -2 }}
                        className={`bg-gradient-to-br ${info.bgClass} border ${info.borderClass} rounded-2xl p-5`}
                    >
                        <div className="flex items-center gap-3 mb-3">
                            <info.icon className={`w-6 h-6 text-${info.color}-600`} />
                            <h3 className="font-bold text-brand-800 dark:text-white">{info.title}</h3>
                        </div>
                        <p className="text-sm text-slate-600 dark:text-slate-400">{info.description}</p>
                        <p className="text-3xl font-bold text-brand-800 dark:text-white mt-3">{structureCounts[key]}</p>
                        <p className="text-xs text-slate-500">reps</p>
                    </motion.div>
                ))}
            </div>

            {/* Configuration Area */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Reps List */}
                <SectionCard title="Sales Representatives" subtitle="Select a rep to configure" className="lg:col-span-1">
                    {isLoading ? (
                        <div className="space-y-2">
                            {[...Array(5)].map((_, i) => (
                                <div key={i} className="animate-pulse flex items-center gap-3 p-2">
                                    <div className="h-10 w-10 bg-slate-200 dark:bg-brand-700 rounded-full" />
                                    <div className="space-y-1">
                                        <div className="h-4 w-28 bg-slate-200 dark:bg-brand-700 rounded" />
                                        <div className="h-3 w-20 bg-slate-200 dark:bg-brand-700 rounded" />
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="space-y-1 max-h-[500px] overflow-y-auto">
                            {salesReps?.map(rep => (
                                <button
                                    key={rep.id}
                                    onClick={() => handleSelectRep(rep)}
                                    className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all text-left ${selectedRep?.id === rep.id
                                            ? 'bg-brand-50 dark:bg-brand-800/50 border border-brand-200 dark:border-brand-700'
                                            : 'hover:bg-slate-50 dark:hover:bg-brand-800/30 border border-transparent'
                                        }`}
                                >
                                    <div className="h-10 w-10 rounded-full bg-gradient-to-br from-brand-100 to-brand-200 dark:from-brand-800 dark:to-brand-700 flex items-center justify-center flex-shrink-0">
                                        <span className="text-brand-700 dark:text-brand-200 font-bold">{rep.firstName?.[0]}{rep.lastName?.[0]}</span>
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-sm font-semibold text-brand-800 dark:text-white truncate">{rep.firstName} {rep.lastName}</p>
                                        <p className="text-xs text-slate-500 truncate">{rep.email}</p>
                                    </div>
                                    {rep.commission ? (
                                        <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${rep.commission.structure === 'commission_only' ? 'bg-gold-100 text-gold-700' :
                                                rep.commission.structure === 'salary_only' ? 'bg-teal-100 text-teal-700' :
                                                    'bg-brand-100 text-brand-700'
                                            }`}>
                                            {rep.commission.structure === 'commission_only' ? `${rep.commission.commissionPercentage}%` :
                                                rep.commission.structure === 'salary_only' ? `$${rep.commission.baseSalary}` :
                                                    `$${rep.commission.baseSalary} + ${rep.commission.commissionPercentage}%`}
                                        </span>
                                    ) : (
                                        <span className="text-xs text-slate-400">Not set</span>
                                    )}
                                </button>
                            ))}
                            {(!salesReps || salesReps.length === 0) && (
                                <p className="text-center text-slate-500 py-8">No sales representatives found.</p>
                            )}
                        </div>
                    )}
                </SectionCard>

                {/* Configuration Form */}
                <SectionCard title={selectedRep ? `Configure: ${selectedRep.firstName} ${selectedRep.lastName}` : 'Commission Configuration'} subtitle={selectedRep ? 'Set earning structure' : 'Select a rep to begin'} className="lg:col-span-2">
                    {!selectedRep ? (
                        <div className="text-center py-12">
                            <CogIcon className="w-16 h-16 text-slate-300 dark:text-slate-600 mx-auto mb-4" />
                            <h3 className="text-lg font-semibold text-brand-800 dark:text-white mb-2">No Rep Selected</h3>
                            <p className="text-slate-500 max-w-sm mx-auto">Select a sales representative from the list to configure their commission structure.</p>
                        </div>
                    ) : (
                        <form onSubmit={handleSubmit} className="space-y-5">
                            {/* Current Structure Display */}
                            {selectedRep.commission && (
                                <div className="p-4 bg-slate-50 dark:bg-brand-800/50 rounded-xl">
                                    <p className="text-xs text-slate-500 mb-1">Current Structure</p>
                                    <p className="font-semibold text-brand-800 dark:text-white capitalize">
                                        {selectedRep.commission.structure?.replace(/_/g, ' ')}
                                        {selectedRep.commission.baseSalary > 0 && ` • $${selectedRep.commission.baseSalary}/mo`}
                                        {selectedRep.commission.commissionPercentage > 0 && ` • ${selectedRep.commission.commissionPercentage}%`}
                                    </p>
                                </div>
                            )}

                            {/* Structure Select */}
                            <div>
                                <label className="block text-xs font-semibold text-brand-800 dark:text-slate-200 mb-2">
                                    Commission Structure <span className="text-rose-500">*</span>
                                </label>
                                <div className="grid grid-cols-3 gap-3">
                                    {Object.entries(structureInfo).map(([key, info]) => (
                                        <button
                                            key={key}
                                            type="button"
                                            onClick={() => setStructure(key)}
                                            className={`p-4 rounded-xl border-2 text-center transition-all ${structure === key
                                                    ? `border-${info.color}-500 bg-${info.color}-50 dark:bg-${info.color}-900/20`
                                                    : 'border-slate-200 dark:border-brand-700 hover:border-slate-300'
                                                }`}
                                        >
                                            <info.icon className={`w-6 h-6 mx-auto mb-2 ${structure === key ? `text-${info.color}-600` : 'text-slate-400'}`} />
                                            <p className="text-xs font-semibold text-brand-800 dark:text-white">{info.title}</p>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Dynamic Fields */}
                            <AnimatePresence>
                                {['salary_only', 'salary_plus_commission'].includes(structure) && (
                                    <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }}>
                                        <label className="block text-xs font-semibold text-brand-800 dark:text-slate-200 mb-2">
                                            Base Salary ($/month) <span className="text-rose-500">*</span>
                                        </label>
                                        <div className="relative">
                                            <CurrencyDollarIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                                            <input
                                                type="number"
                                                value={baseSalary}
                                                onChange={(e) => setBaseSalary(e.target.value)}
                                                className="w-full pl-12 pr-4 py-3 border-2 border-slate-200 dark:border-brand-700 rounded-xl text-sm dark:bg-brand-800 dark:text-white focus:ring-2 focus:ring-brand-500/20 focus:border-brand-500"
                                                placeholder="50000"
                                            />
                                        </div>
                                    </motion.div>
                                )}

                                {['commission_only', 'salary_plus_commission'].includes(structure) && (
                                    <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }}>
                                        <label className="block text-xs font-semibold text-brand-800 dark:text-slate-200 mb-2">
                                            Commission Percentage (%) <span className="text-rose-500">*</span>
                                        </label>
                                        <div className="relative">
                                            <PercentIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                                            <input
                                                type="number"
                                                step="0.1"
                                                min="0"
                                                max="100"
                                                value={commissionPercentage}
                                                onChange={(e) => setCommissionPercentage(e.target.value)}
                                                className="w-full pl-12 pr-4 py-3 border-2 border-slate-200 dark:border-brand-700 rounded-xl text-sm dark:bg-brand-800 dark:text-white focus:ring-2 focus:ring-brand-500/20 focus:border-brand-500"
                                                placeholder="10"
                                            />
                                        </div>
                                    </motion.div>
                                )}
                            </AnimatePresence>

                            {/* Summary */}
                            {structure && (
                                <motion.div
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    className="p-5 bg-gradient-to-r from-brand-50 to-brand-100 dark:from-brand-800/30 dark:to-brand-900/30 rounded-xl border border-brand-200 dark:border-brand-700"
                                >
                                    <h4 className="font-semibold text-brand-800 dark:text-white mb-3 flex items-center gap-2">
                                        <CheckCircleIcon className="w-5 h-5 text-emerald-500" />
                                        Earnings Summary
                                    </h4>
                                    <div className="space-y-2 text-sm">
                                        {structure === 'commission_only' && (
                                            <p className="text-slate-600 dark:text-slate-400">
                                                Earns <strong className="text-brand-800 dark:text-white">{commissionPercentage || 0}%</strong> commission on each completed order.
                                            </p>
                                        )}
                                        {structure === 'salary_only' && (
                                            <p className="text-slate-600 dark:text-slate-400">
                                                Earns <strong className="text-brand-800 dark:text-white">${baseSalary || 0}/month</strong> fixed salary.
                                            </p>
                                        )}
                                        {structure === 'salary_plus_commission' && (
                                            <>
                                                <p className="text-slate-600 dark:text-slate-400">
                                                    Base salary: <strong className="text-brand-800 dark:text-white">${baseSalary || 0}/month</strong>
                                                </p>
                                                <p className="text-slate-600 dark:text-slate-400">
                                                    Commission: <strong className="text-brand-800 dark:text-white">{commissionPercentage || 0}%</strong> per order
                                                </p>
                                            </>
                                        )}
                                    </div>
                                </motion.div>
                            )}

                            {/* Submit Button */}
                            <div className="flex gap-3 pt-2">
                                <button type="button" onClick={resetForm} className="flex-1 px-5 py-2.5 border-2 border-slate-300 dark:border-brand-600 rounded-xl hover:bg-white dark:hover:bg-brand-800 transition font-medium text-sm">
                                    Clear
                                </button>
                                <button
                                    type="submit"
                                    disabled={updateMutation.isLoading || !hasValidStructure}
                                    className="flex-1 px-6 py-2.5 bg-gradient-to-r from-brand-700 to-brand-900 text-white rounded-xl hover:from-brand-800 hover:to-brand-950 transition-all font-semibold text-sm shadow-lg shadow-brand-500/25 disabled:opacity-50"
                                >
                                    {updateMutation.isLoading ? (
                                        <span className="flex items-center justify-center gap-2">
                                            <ArrowPathIcon className="w-4 h-4 animate-spin" />
                                            Saving...
                                        </span>
                                    ) : 'Save Commission'}
                                </button>
                            </div>
                        </form>
                    )}
                </SectionCard>
            </div>
        </div>
    );
};

export default CommissionSettings;
